svg.script:
(function() {
  var svg = document.getElementById('fm1p12-svg');
  var tt = document.getElementById('fm1p12-tooltip');
  var ttTitle = document.getElementById('fm1p12-tt-title');
  var ttBody = document.getElementById('fm1p12-tt-body');

  window.fm1p12SetScene = function(scene) {
    if (svg) {
      svg.setAttribute('data-scene', scene);
    }
  };

  window.fm1p12ShowTT = function(evt, title, body) {
    if (!tt || !svg) return;
    ttTitle.textContent = title;
    ttBody.textContent = body;

    var ctm = svg.getScreenCTM();
    if (ctm) {
      var pt = svg.createSVGPoint();
      pt.x = evt.clientX;
      pt.y = evt.clientY;
      var loc = pt.matrixTransform(ctm.inverse());

      var x = loc.x + 12;
      var y = loc.y + 12;
      if (x + 230 > 1180) x = loc.x - 230;
      if (y + 50 > 830) y = loc.y - 50;

      tt.setAttribute('transform', 'translate(' + x + ',' + y + ')');
      tt.setAttribute('class', 'fm1p12-visible');
    }
  };

  window.fm1p12HideTT = function() {
    if (tt) {
      tt.setAttribute('class', '');
    }
  };
})();
